"""Server-rendered topic roadmap; enhancement is optional and page-specific."""
import json
from html import escape as esc
from cms_loader import CONTENT, load_yaml
from learning_journey import journey_catalog


def render_roadmap():
    data = load_yaml(CONTENT / "learning-roadmap.yaml")
    paths = data["paths"]
    topics = [t for p in paths for t in p["topics"]]
    if (len(paths) != 10 or any(len(p["topics"]) != 10 for p in paths)
            or len(topics) != 100 or len({t["id"] for t in topics}) != 100
            or {t["number"] for t in topics} != set(range(1, 101))):
        raise ValueError("Learning roadmap requires 100 distinct topics")
    ready = sum(bool(t["href"]) for t in topics)
    starter_ids = ["topic-011", "topic-031", "topic-034", "topic-051", "topic-063"]
    route = journey_catalog()["beginner_route"]
    starter = []
    for i, (step, topic_id) in enumerate(zip(route["steps"], starter_ids), 1):
        starter.append(f'''<li><span class="lr-step-number">0{i}</span><div><h3><a href="/guides/{esc(step['slug'])}.html">{esc(step['label'])}</a></h3><p>{esc(step['learn'])}</p><details><summary>Parts &amp; before you start</summary><p>{esc(step['parts'])}</p><p>{esc(step['ready'])}</p></details><label class="lr-done" hidden><input type="checkbox" data-complete="{topic_id}"> I completed this step<span class="lr-sr">: {esc(step["label"])}</span></label></div></li>''')
    cards = []
    nav = []
    for n, path in enumerate(paths, 1):
        pid = esc(path['id'])
        aliases = {'foundations':['beginner'], 'sensor-basics':['explorer'], 'iot-basics':['iot'], 'robotics-basics':['builder','advanced']}.get(path['id'], [])
        alias_html = ''.join(f'<span id="{a}"></span>' for a in aliases)
        linked = sum(bool(t["href"]) for t in path["topics"])
        nav.append(f'<a href="#{pid}"><span>{n:02}</span>{esc(path["label"])}</a>')
        rows = []
        for t in path["topics"]:
            title = esc(t['title'])
            if t['href']:
                control = f'''<a href="{esc(t['href'])}" data-study="{t['id']}">Study guide <span aria-hidden="true">↗</span><span class="lr-sr">: {title}</span></a><button type="button" data-preview="{t['id']}" hidden>Quick activity<span class="lr-sr">: {title}</span></button><label class="lr-done" hidden><input type="checkbox" data-complete="{t['id']}"> Done<span class="lr-sr">: {title}</span></label>'''
                status = '<span class="lr-state">Guide linked</span>'
            else:
                control = '<span class="lr-planned-note">No dedicated lesson linked yet</span>'
                status = '<span class="lr-state lr-planned">Planned</span>'
            rows.append(f'''<li class="lr-topic" id="{t['id']}" data-ready="{str(bool(t['href'])).lower()}"><span class="lr-topic-number">{t['number']:03}</span><div><div class="lr-topic-top">{status}</div><h4>{title}</h4><div class="lr-topic-actions">{control}</div></div></li>''')
        cards.append(f'''<details class="lr-path" id="{pid}" data-level="{esc(path['level'])}"><summary><span class="lr-path-number">{n:02}</span><span class="lr-path-title"><span class="lr-kicker">{esc(path['level'])} · {linked} linked topics / 10</span><h3 id="{pid}-heading">{esc(path['label'])}</h3><span class="lr-path-description">{esc(path['description'])}</span></span><span class="lr-expand" aria-hidden="true">+</span></summary><div class="lr-path-body">{alias_html}<p class="lr-path-outcome"><strong>Your goal:</strong> {esc(path['outcome'])}</p><ol class="lr-topic-list">{''.join(rows)}</ol></div></details>''')
    # JSON is data, not executable; neutralize closing script sequences.
    payload = json.dumps(dict(paths=paths, starter_ids=starter_ids), ensure_ascii=False).replace('<', '\\u003c')
    return f'''
<div class="lr" id="learning-roadmap">
<a class="lr-skip" href="#esp32-basics">Skip to beginner steps</a>
<nav class="lr-breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span aria-current="page">Learning</span></nav>
<section class="lr-hero" aria-labelledby="lr-title"><div><p class="lr-eyebrow">YOUR NEXT SKILL STARTS HERE</p><h1 id="lr-title">Learn ESP32.<br> <em>Build what’s next.</em></h1><p class="lr-lead">Learn ESP32, one working build at a time. A clear route from your first Arduino IDE upload to sensors, displays and connected projects.</p><div class="lr-actions"><a class="lr-primary" href="#esp32-basics">I’m new to ESP32 <span aria-hidden="true">→</span></a><a class="lr-secondary" href="#explore-paths">I know the basics</a></div><div class="lr-stats"><span><strong>10</strong> skill paths</span><span><strong>100</strong> roadmap topics</span><span><strong>5</strong> beginner steps</span></div></div><div class="lr-hero-art"><img src="/assets/visuals/guides/photos/beginner-media/esp32-blink-led-on-photo.webp" width="1600" height="900" fetchpriority="high" alt="Contributor’s real ESP32 breadboard build with an external green LED lit"><div class="lr-art-caption"><span class="lr-dot" aria-hidden="true"></span><div><strong>Your first small win</strong><span>A real external-LED build from our community</span></div><a href="/guides/blink-led-esp32.html#recorded-media" aria-label="See the real Blink build photos">↗</a></div></div></section>
<section class="lr-continue" hidden aria-labelledby="lr-continue-title"><div><p class="lr-eyebrow">MAKE A LITTLE PROGRESS</p><h2 id="lr-continue-title">Your next step is ready.</h2><p id="lr-next-label">Start with your first successful upload.</p><a id="lr-next" class="lr-primary" href="/guides/installing-arduino-ide-esp32.html">Start learning →</a></div><div class="lr-progress-box"><label for="lr-progress">Your self-marked progress</label><progress id="lr-progress" value="0" max="{ready}"></progress><p id="lr-progress-label">0 of {ready} linked topics completed</p><label class="lr-save"><input id="lr-save" type="checkbox"> Save progress on this device</label><p class="lr-small" id="lr-storage-note">Optional. Your progress stays in this browser; no account or device sync.</p><button id="lr-reset" type="button">Clear my progress</button><p id="lr-status" role="status" aria-live="polite"></p></div></section>
<section id="esp32-basics" class="lr-beginner" aria-labelledby="lr-start-title"><div class="lr-section-head"><div><p class="lr-eyebrow">THE BEST PLACE TO BEGIN</p><h2 id="lr-start-title"><span id="esp32-basics-heading"></span>Five steps. Your first working builds.</h2></div><span class="lr-pill">BEGINNER ROUTE</span></div><p>Start with a classic ESP32 DevKit. Follow each guide’s exact board, wiring and software assumptions. These are learning steps, not promised completion times.</p><ol class="lr-starter">{''.join(starter)}</ol><p class="lr-small">Need the background first? <a href="/guides/what-is-esp32.html">What is ESP32?</a> · <a href="/components/esp32-devkit.html">Read your board’s pinout</a></p></section>
<section class="lr-kit" hidden aria-labelledby="lr-kit-title"><div><p class="lr-eyebrow">START WITH WHAT YOU HAVE</p><h2 id="lr-kit-title">A drawer of parts.<br>A starting point.</h2><p>Choose your kit to find the next beginner exercise. Check the guide’s full parts list before wiring.</p></div><form id="lr-kit-form"><label for="lr-kit-select">What’s on your desk?</label><select id="lr-kit-select"><option value="board">ESP32 + USB data cable</option><option value="led">Board + external LED + resistor + breadboard</option><option value="button">Working LED circuit + pushbutton</option><option value="dht">Board + DHT11 + required pull-up arrangement</option><option value="oled">Board + compatible SSD1306 I2C OLED</option></select><button class="lr-primary" type="submit">Find my starting point →</button><p id="lr-kit-result" role="status">No parts yet? Start with the board introduction and read the setup guide.</p></form></section>
<section id="explore-paths" class="lr-explore" aria-labelledby="lr-explore-title"><div class="lr-section-head"><div><p class="lr-eyebrow">FOLLOW YOUR CURIOSITY</p><h2 id="lr-explore-title">One roadmap. Ten ways forward.</h2></div><a href="/guides.html" class="lr-underlined">Browse all guides ↗</a></div><p>{ready} topics link to existing guides or sections; several share one complete guide. The other {100-ready} are planned topics, not available lessons. Choose a path and build on what you know.</p><div class="lr-filters" hidden><label>Find a topic<input id="lr-search" type="search" placeholder="Try DHT11, OLED or Wi-Fi" autocomplete="off"></label><label>Experience<select id="lr-level"><option value="all">All levels</option><option>Beginner</option><option>Intermediate</option></select></label><label>Availability<select id="lr-availability"><option value="all">All roadmap topics</option><option value="ready">With a study guide</option><option value="planned">Planned topics</option></select></label><button type="button" id="lr-clear">Clear filters</button><p id="lr-results" role="status">100 topics across 10 paths</p></div><div class="lr-map-layout"><nav class="lr-path-nav" aria-label="Choose a skill path">{''.join(nav)}</nav><div class="lr-paths">{''.join(cards)}<p id="lr-no-results" hidden>No topics match. Try another word or clear your filters.</p></div></div></section>
<section id="learning-desk" class="lr-desk" hidden aria-labelledby="lr-desk-title"><p class="lr-eyebrow">YOUR LEARNING DESK</p><h2 id="lr-desk-title" tabindex="-1">A small activity. A useful next step.</h2><p id="lr-desk-topic"></p><div class="lr-desk-grid"><div><h3>What you’re working towards</h3><p id="lr-outcome"></p><h3>Check your parts</h3><p id="lr-parts"></p><h3>Try this</h3><p id="lr-challenge"></p><a id="lr-desk-guide" class="lr-primary" href="/guides/what-is-esp32.html">Open the study guide ↗</a></div><form id="lr-quiz"><fieldset><legend id="lr-question"></legend><div id="lr-answers"></div></fieldset><button class="lr-primary" type="submit">Check my answer</button><p id="lr-feedback" role="status"></p></form></div><div class="lr-desk-footer"><button id="lr-desk-done" type="button">Mark topic complete</button><button id="lr-desk-next" type="button">Next linked topic →</button><a href="#explore-paths">Back to all paths ↑</a></div><p class="lr-small">A path-level knowledge check, not a certificate or proof of hardware testing. Mark a topic complete when you are satisfied you understand it.</p></section>
<section class="lr-help" aria-labelledby="lr-help-title"><div><p class="lr-eyebrow">STUCK IS PART OF LEARNING</p><h2 id="lr-help-title">Find the next thing to check.</h2><p>Return to a simple working example before adding another component.</p></div><div><a href="/guides/installing-arduino-ide-esp32.html#setup-troubleshooting">My board won’t upload <span>→</span></a><a href="/guides/pull-up-vs-pull-down-resistors.html">My button readings jump around <span>→</span></a><a href="/guides/esp32-dht22.html">My DHT11 readings fail <span>→</span></a><a href="/guides/oled-display-esp32.html">My OLED stays blank <span>→</span></a><a href="/guides/esp32-wifi-troubleshooting.html">My Wi-Fi won’t connect <span>→</span></a></div></section>
<section class="lr-faq" aria-labelledby="lr-faq-title"><p class="lr-eyebrow">BEFORE YOU START</p><h2 id="lr-faq-title">A few good questions.</h2><details><summary>Can I learn ESP32 without programming experience?</summary><p>Begin with the board introduction and Arduino IDE setup. Follow a complete example, change one thing and check the result. Standalone programming topics marked planned do not have dedicated lessons yet.</p></details><details><summary>Does this roadmap contain 100 complete tutorials?</summary><p>No. It is a 100-topic curriculum map. “Guide linked” means an existing study guide or section covers the topic. Several topics can share a guide. Planned topics are future curriculum ideas and have no lesson link.</p></details><details><summary>Will my progress sync to my phone?</summary><p>No. Progress starts in this tab. If you enable saving, it is kept in this browser on this device. Private browsing, clearing site data or changing device can remove it. There is no account or server sync.</p></details><details><summary>Can I skip straight to IoT or robotics?</summary><p>You can open any path. First verify that you can upload, read a simple input and control a safe output. For motors or powered loads, follow the exact driver and supply requirements; never power a motor from GPIO.</p></details></section>
<noscript><p class="lr-notice">All topics and guide links work without JavaScript. Progress, topic filters, kit suggestions and knowledge checks need JavaScript.</p></noscript>
<script type="application/json" id="lr-data">{payload}</script>
</div>'''
